+    private range: ts.TextSpan,
+  ) {}
+
+  getSpans(): number[] {
+    return this.spans;
+  }
+
+  visit(node: TmplAstNode | null) {
+    if (node && this.rangeIntersectsWith(node.sourceSpan)) {
+      node.visit(this);
+    }
+  }
