-}
-
-function isSsrContentsIntegrityMarker(el: Node): boolean {
-  return (
-    el.nodeType === Node.COMMENT_NODE && el.textContent?.trim() === SSR_CONTENT_INTEGRITY_MARKER
-  );
-}
