+ * found in the LICENSE file at https://angular.dev/license
+ */
+
+import {FilterFn, FilterFnGenerator, FilterMatch} from './filter.component';
+
+//
+// Types & Constants
+//
+
+type TokenType =
+  | 'opening_bracket'
+  | 'closing_bracket'
+  | 'chevron_left'
+  | 'chevron_right'
+  | 'slash'
+  | 'space'
+  | 'text';
+
+interface Token {
+  type: TokenType;
+  value: string;
+  idx: number;
+}
+
+const TERMINAL_CHAR = ['[', ']', '<', '>', '/', ' '];
+const CHAR_TO_TOKEN: {[key: string]: TokenType} = {
+  '[': 'opening_bracket',
+  ']': 'closing_bracket',
+  '<': 'chevron_left',
+  '>': 'chevron_right',
+  '/': 'slash',
+  ' ': 'space',
+};
+
+interface ParsedValue {
+  value: string;
+  idx: number;
+}
+
+export interface ParsedFilter {
+  component?: ParsedValue;
+  directives: ParsedValue[];
+  element?: ParsedValue;
+}
+
+//
+// Helpers
+//
+
+function toParserValue(token: Token): ParsedValue {
+  return {
+    value: token.value,
+    idx: token.idx,
+  };
+}
+
+function checkForMatch(filter?: ParsedValue, target?: ParsedValue): FilterMatch | null {
+  if (!filter || !target) {
+    return null;
+  }
+  const startIdx = target.value.indexOf(filter.value);
+
+  if (startIdx > -1) {
+    const start = startIdx + target.idx;
+    return {
+      startIdx: start,
